import {readFileSync,writeFileSync,readdirSync,mkdirSync,statfsSync} from 'node:fs';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import {discoverInventory,sourceHash} from '../scripts/quality-inventory';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
const mode=process.argv[2];if(!['current','native'].includes(mode!))throw Error('Choose current/native');
const root=process.cwd();function testsUnder(dir:string):string[]{return readdirSync(dir,{withFileTypes:true}).flatMap(e=>e.isDirectory()?testsUnder(dir+'/'+e.name):e.isFile()&&e.name.endsWith('.test.ts')?[dir+'/'+e.name]:[]);}
const groups=[{name:'database',files:[...testsUnder('src/infrastructure/database'),...testsUnder('tests/infrastructure/database'),...testsUnder('tests/integration/infrastructure/database')]},{name:'cli',files:[...testsUnder('src/presentation/cli'),'tests/helpers/capture-json.test.ts']},{name:'application',files:[...testsUnder('src/application'),'src/infrastructure/security/secret-audit-service.test.ts','scripts/eval-v5.test.ts']}];
const sourceInputs=discoverInventory(root).files.map(f=>({path:f.path,sourceHash:f.sourceHash}));
const extras=['bunfig.toml','package.json','bun.lock',...readdirSync('docs/evals/fixtures/v5').filter(f=>f.endsWith('.json')).map(f=>'docs/evals/fixtures/v5/'+f)].map(path=>({path,sourceHash:sourceHash(readFileSync(path,'utf8'))}));sourceInputs.push(...extras);
const free=statfsSync(root);if(free.bavail*free.bsize<536870912)throw Error('Runtime verification requires512MiB free');
const storage=createOwnedTestDirectory('memory-combined-native-'),runs:any[]=[];
const url='https://github.com/oven-sh/bun/releases/download/bun-v1.3.14/bun-windows-x64.zip',digest='0a0620930b6675d7ba440e81f4e0e00d3cfbe096c4b140d3fff02205e9e18922';
let executable=process.execPath;
try{
 if(mode==='native'){
 const response=await fetch(url);if(!response.ok)throw Error('Runtime HTTP '+response.status);const bytes=Buffer.from(await response.arrayBuffer());if(bytes.length!==38366737||createHash('sha256').update(bytes).digest('hex')!==digest)throw Error('Runtime release identity mismatch');
 const archive=join(storage.dir,'bun.zip'),destination=join(storage.dir,'runtime');writeFileSync(archive,bytes);mkdirSync(destination);const script=join(storage.dir,'expand.ps1');writeFileSync(script,'param([string]$Archive,[string]$Destination)\n$ErrorActionPreference="Stop"\nExpand-Archive -LiteralPath $Archive -DestinationPath $Destination\n');
 const expanded=Bun.spawnSync(['powershell.exe','-NoProfile','-NonInteractive','-File',script,archive,destination],{stdout:'pipe',stderr:'pipe',timeout:45000});if(expanded.exitCode!==0)throw Error(new TextDecoder().decode(expanded.stderr));executable=join(destination,'bun-windows-x64/bun.exe');
 }
 for(const group of groups){
 console.log('Starting '+mode+' '+group.name+' ('+group.files.length+' files)');
 const command=[executable,'test','--timeout','15000',...group.files];
 const child=Bun.spawn(command,{env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe'});
 const [stdout,stderr,exit]=await Promise.all([new Response(child.stdout).text(),new Response(child.stderr).text(),child.exited]);const output=stdout+stderr;
 runs.push({name:group.name,files:group.files,command,exit,output});
 for(const row of sourceInputs)if(sourceHash(readFileSync(row.path,'utf8'))!==row.sourceHash)throw Error('Source changed '+row.path);
 writeFileSync('.git/b11-combined-'+mode+'.json',JSON.stringify({recordedAt:new Date().toISOString(),startingRevision:'edc079d0ebe15f69a3e372c0291384a4dcb36282',mode,url,digest,sourceInputs,groups,runs,source:readFileSync('.git/b11-combined-run.ts','utf8')},null,2)+'\n');
 console.log(output.slice(-260));if(exit!==0)throw Error('Combined '+group.name+' group failed; full output retained');
 }
}finally{storage.cleanup();}

