db.transaction(() => {
        db.exec("DROP TRIGGER IF EXISTS sessions_fts_update; DROP TRIGGER IF EXISTS sessions_fts_delete;");
        db.exec(SESSIONS_FTS_TRIGGERS);
        db.exec("DELETE FROM sessions_fts;");
        db.exec(`INSERT INTO sessions_fts(session_id, summary)
            SELECT id, summary FROM sessions WHERE summary IS NOT NULL AND summary != ''`);
    })();

using statement = db.prepare<{ busy: number; log: number; checkpointed: number }, []>(
        "PRAGMA wal_checkpoint(TRUNCATE);"
    );

using statement = this.db.prepare<FrictionRow, [number]>(
                "SELECT * FROM friction_log WHERE id = ?"
            );

using statement = this.db.prepare<FrictionRow, []>(
                "SELECT * FROM friction_log WHERE status = 'open' ORDER BY logged_at DESC"
            );

using countStatement = this.db.prepare<{ count: number }, (string | number)[]>(
            `SELECT COUNT(*) as count FROM friction_log ${whereClause}`
        );

using statement = this.db.prepare<FrictionRow, (string | number)[]>(
            `SELECT * FROM friction_log ${whereClause} ORDER BY logged_at DESC${limitClause}`
        );

using statement = this.db.prepare(
            "UPDATE friction_log SET status = 'resolved', resolution = ?, resolved_at = ? WHERE id = ?"
        );

using statement = this.db.prepare(
            "UPDATE friction_log SET status = ? WHERE id = ?"
        );

using summaryStatement = this.db.prepare<{
            total: number;
            open_count: number;
            resolved_count: number;
            wont_fix_count: number;
            avg_resolve_days: number | null;
        }, []>(`
            SELECT
                COUNT(*) as total,
                COALESCE(SUM(CASE WHEN status = 'open' THEN 1 ELSE 0 END), 0) as open_count,
                COALESCE(SUM(CASE WHEN status = 'resolved' THEN 1 ELSE 0 END), 0) as resolved_count,
                COALESCE(SUM(CASE WHEN status = 'wont-fix' THEN 1 ELSE 0 END), 0) as wont_fix_count,
                AVG(CASE WHEN resolved_at IS NOT NULL
                    THEN julianday(resolved_at) - julianday(logged_at) END) as avg_resolve_days
            FROM friction_log
        `);

using severityStatement = this.db.prepare<{ severity: string; count: number }, []>(
            "SELECT severity, COUNT(*) as count FROM friction_log GROUP BY severity"
        );

using categoryStatement = this.db.prepare<{ category: string; count: number }, []>(
            "SELECT category, COUNT(*) as count FROM friction_log GROUP BY category"
        );

using toolStatement = this.db.prepare<{ tool: string; count: number }, []>(
            "SELECT tool, COUNT(*) as count FROM friction_log GROUP BY tool"
        );

using oldestStatement = this.db.prepare<{
            id: number;
            description: string;
            days_open: number;
        }, []>(`
            SELECT id, description,
                   julianday('now') - julianday(logged_at) as days_open
            FROM friction_log
            WHERE status = 'open'
            ORDER BY logged_at ASC
            LIMIT 1
        `);

using statement = this.db.prepare(
            "UPDATE friction_log SET last_reviewed_at = ? WHERE tool = ? AND status = 'open'"
        );

using statement = this.db.prepare<FrictionRow, [string, string]>(
                "SELECT * FROM friction_log WHERE tool = ? AND category = ? AND status = 'open'"
            );

using statement = this.db.prepare(`
          INSERT INTO facts (
            uuid, type, project, content, metadata, observed_at, superseded_at, superseded_by
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        `);

const transaction = this.db.transaction(() => {
      for (const fact of facts) {
        // Run synchronously within the transaction block.
        const metadataStr = fact.metadata ? JSON.stringify(fact.metadata) : null;
        using lookup = this.db.prepare("SELECT id FROM facts WHERE uuid = ?");
        const existing = lookup.get(fact.uuid) as { id: number } | null;

        if (existing) {
          using statement = this.db.prepare(`
              UPDATE facts
              SET type = ?, project = ?, content = ?, metadata = ?, observed_at = ?, superseded_at = ?, superseded_by = ?, updated_at = datetime('now')
              WHERE uuid = ?
            `);
          statement.run(
              fact.type,
              fact.project,
              fact.content,
              metadataStr,
              fact.observedAt.toISOString(),
              fact.supersededAt ? fact.supersededAt.toISOString() : null,
              fact.supersededBy,
              fact.uuid
            );
          saved.push(fact.withId(existing.id));
        } else {
          using statement = this.db.prepare(`
              INSERT INTO facts (
                uuid, type, project, content, metadata, observed_at, superseded_at, superseded_by
              ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            `);
          const result = statement.run(
              fact.uuid,
              fact.type,
              fact.project,
              fact.content,
              metadataStr,
              fact.observedAt.toISOString(),
              fact.supersededAt ? fact.supersededAt.toISOString() : null,
              fact.supersededBy
            );
          saved.push(fact.withId(Number(result.lastInsertRowid)));
        }
      }
    });

using statement = this.db.prepare(`
              INSERT INTO facts (
                uuid, type, project, content, metadata, observed_at, superseded_at, superseded_by
              ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            `);

const transaction = this.db.transaction((items: GraphEdge[]) => {
      for (const edge of items) {
        using statement = this.db.prepare(`
          INSERT INTO graph_edges (
            edge_id, source_type, source_id, source_label, target_type, target_id,
            target_label, relationship, project, visibility, source_event_ids,
            source_kinds, confidence, valid_from, valid_to, why, metadata,
            created_at, updated_at
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
          ON CONFLICT(edge_id) DO UPDATE SET
            source_type = excluded.source_type,
            source_id = excluded.source_id,
            source_label = excluded.source_label,
            target_type = excluded.target_type,
            target_id = excluded.target_id,
            target_label = excluded.target_label,
            relationship = excluded.relationship,
            project = excluded.project,
            visibility = excluded.visibility,
            source_event_ids = excluded.source_event_ids,
            source_kinds = excluded.source_kinds,
            confidence = excluded.confidence,
            valid_from = excluded.valid_from,
            valid_to = excluded.valid_to,
            why = excluded.why,
            metadata = excluded.metadata,
            updated_at = excluded.updated_at
        `);
        statement.run(...this.toSqlParams(edge));
      }
      const saved: GraphEdge[] = [];
      for (const edge of items) {
        const current = this.findEdge(edge.edgeId);
        if (!current) throw new Error("Graph edge was not present after batch save");
        saved.push(current);
      }
      return saved;
    });

using statement = this.db.prepare<GraphEdgeRow, [string]>(
      "SELECT * FROM graph_edges WHERE edge_id = ?",
    );

using statement = this.db.prepare<GraphEdgeRow, (string | number)[]>(`
      SELECT * FROM graph_edges
      WHERE ${conditions.join(" AND ")}
      ORDER BY confidence DESC, updated_at DESC, edge_id ASC
      LIMIT ?
    `);

using statement = this.db.prepare(
      "DELETE FROM graph_edges WHERE valid_to IS NOT NULL AND valid_to < ?",
    );

using statement = this.db.prepare<GovernanceRow, [string, string]>(
      "SELECT * FROM memory_governance WHERE surface = ? AND target_id = ?",
    );

using statement = this.db.prepare<GovernanceRow, string[]>(
      `SELECT * FROM memory_governance WHERE surface = ? AND target_id IN (${placeholders})`,
    );

using statement = this.db.prepare<GovernanceRow, (string | number)[]>(
      `SELECT * FROM memory_governance ${where} ORDER BY updated_at DESC LIMIT ?`,
    );

return this.db.transaction(() => {
      this.recordGovernanceEvent(event, control, surface, targetId, governance);

      if (control === "register") {
        return this.saveEntry(entryFromEvent(event, governance, surface, targetId));
      }

      const existing = this.findEntry(surface, targetId);
      const base = existing ?? entryFromEvent(event, governance, surface, targetId);
      const updated = base.withControl({
        control,
        actor: stringValue(governance.actor, event.provenance.actor),
        reason: optionalString(governance.reason),
        occurredAt: event.occurredAt,
        expiresAt: optionalDate(governance.expiresAt ?? governance.expires_at),
        consentStatus: optionalConsentStatus(governance.consentStatus ?? governance.consent_status),
        consentScopes: optionalStringArray(governance.consentScopes ?? governance.consent_scopes),
        lastEventId: event.eventId,
      });
      return this.saveEntry(updated);
    })();

this.db.transaction(() => {
      this.db.exec("DELETE FROM memory_governance_events; DELETE FROM memory_governance;");
    })();

using statement = this.db.prepare(`
      INSERT INTO memory_governance_events (
        event_id, kind, control, surface, target_id, actor, reason, occurred_at, payload
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(event_id) DO NOTHING
    `);

using statement = this.db.prepare<DreamRow, [string]>(
      "SELECT * FROM dream_entries WHERE dream_id = ?",
    );

using statement = this.db.prepare<DreamRow, (string | number)[]>(
      `SELECT * FROM dream_entries ${where} ORDER BY updated_at DESC, dream_id ASC LIMIT ?`,
    );

return finalize(fixture, checks, {
    finding_kinds: [...new Set(result.findings.map((finding) => finding.kind))],
    finding_hashes: result.findings.map((finding) => finding.hash),
    redacted_length: result.text.length,
  });

return finalize(fixture, checks, {
    visible_ids: visibleIds,
    section_keys: context?.sections.map((section) => section.key) ?? [],
  });

return finalize(fixture, checks, {
      visible_ids: visibleIds,
      include_historical: includeHistorical,
      persisted_fact_count: stored.length,
    });

return finalize(fixture, checks, {
    failure_step: failureStep,
    backup_available: isNonEmptyString(input.backupRef),
    post_failure_steps: stepsAfterFailure,
    behavior_backed: false,
  });

return finalize(fixture, checks, {
    entry_count: entries.length,
    generated_entry_ids: entries.map((entry) => entry.entryId),
    generated_kinds: entries.map((entry) => entry.kind),
    governance_count: governanceRepo.saved.length,
  });

return finalize(fixture, checks, {
      visible_edge_ids: visibleIds,
      persisted_edge_count: (await graphRepo.findCurrent({ project, asOf, minConfidence: 0 })).length,
      governance_count: (await governanceRepo.findAll({ surface: "graph" })).length,
    });

return finalize(fixture, checks, {
    ranked_ids: ranked.map((candidate) => candidate.id),
    top_score: ranked[0]?.score ?? null,
    top_why_included: ranked[0]?.whyIncluded ?? null,
    behavior_backed: fixture.mode === "behavior",
  });

const commitSession = this.db.transaction(() => {
        // Save session
        this.sessionRepo.save(sessionEntity);

        // Save messages
        if (messages.length > 0) {
          this.messageRepo.saveMany(
            messages.map((m) => ({ message: m, sessionId: session.id }))
          );
        }

        // Save tool uses
        if (toolUses.length > 0) {
          this.toolUseRepo.saveMany(
            toolUses.map((t) => ({ toolUse: t, sessionId: session.id }))
          );
        }

        // Update extraction state to complete
        const completedState = state
          .startProcessing()
          .incrementMessages(messages.length)
          .complete(new Date());
        this.extractionStateRepo.save(completedState);
      });

using sessionsStatement = db.prepare<SessionExport, []>(`SELECT id, project_path_encoded as projectPathEncoded,
              project_path_decoded as projectPathDecoded,
              project_name as projectName,
              start_time as startTime, end_time as endTime,
              message_count as messageCount, summary
       FROM sessions`);

using messagesStatement = db.prepare<MessageExport, []>(`SELECT id, session_id as sessionId, role, content, timestamp,
              tool_use_ids as toolUseIds
       FROM messages_meta`);

using linksStatement = db.prepare<LinkExport, []>(`SELECT source_type as sourceType, source_id as sourceId,
              target_type as targetType, target_id as targetId,
              relationship, weight
       FROM links`);

using extractionStatesStatement = db.prepare<ExtractionStateExport, []>(`SELECT id, session_path as sessionPath, started_at as startedAt,
              status, completed_at as completedAt,
              messages_extracted as messagesExtracted,
              error_message as errorMessage,
              file_mtime as fileMtime, file_size as fileSize
       FROM extraction_state`);

using factsStatement = db.prepare<FactExport, []>(`SELECT uuid, type, project, content, metadata,
              observed_at as observedAt, superseded_at as supersededAt,
              superseded_by as supersededBy
       FROM facts`);

const importData = db.transaction(() => {
    // Replacement and inserts share one rollback boundary.
    if (options.clearExisting) clearAllTables(db);
    const stats = { sessions: 0, messages: 0, toolUses: 0, entities: 0, links: 0, facts: 0 };
    // Import sessions first (referenced by messages, tool_uses)
    using insertSession = db.prepare(`
      INSERT INTO sessions
        (id, project_path_encoded, project_path_decoded, project_name,
         start_time, end_time, message_count, summary)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT DO NOTHING RETURNING 1 AS inserted
    `);

    for (const s of data.sessions) {
      stats.sessions += insertSession.get(
        s.id,
        s.projectPathEncoded,
        s.projectPathDecoded,
        s.projectName,
        s.startTime,
        s.endTime,
        s.messageCount,
        s.summary
      ) ? 1 : 0;
    }

    // Import messages (triggers will update FTS5)
    using insertMessage = db.prepare(`
      INSERT INTO messages_meta
        (id, session_id, role, content, timestamp, tool_use_ids)
      VALUES (?, ?, ?, ?, ?, ?)
      ON CONFLICT DO NOTHING RETURNING 1 AS inserted
    `);

    for (const m of data.messages) {
      stats.messages += insertMessage.get(
        m.id,
        m.sessionId,
        m.role,
        m.content,
        m.timestamp,
        m.toolUseIds
      ) ? 1 : 0;
    }

    // Import tool uses
    using insertToolUse = db.prepare(`
      INSERT INTO tool_uses
        (id, session_id, name, input, timestamp, status, result)
      VALUES (?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT DO NOTHING RETURNING 1 AS inserted
    `);

    for (const t of data.toolUses) {
      stats.toolUses += insertToolUse.get(
        t.id,
        t.sessionId,
        t.name,
        t.input,
        t.timestamp,
        t.status,
        t.result
      ) ? 1 : 0;
    }

    // Import entities
    using insertEntity = db.prepare(`
      INSERT INTO entities
        (id, type, name, metadata, confidence)
      VALUES (?, ?, ?, ?, ?)
      ON CONFLICT DO NOTHING RETURNING 1 AS inserted
    `);

    for (const e of data.entities) {
      stats.entities += insertEntity.get(e.id, e.type, e.name, e.metadata, e.confidence) ? 1 : 0;
    }

    // Import links
    using insertLink = db.prepare(`
      INSERT INTO links
        (source_type, source_id, target_type, target_id, relationship, weight)
      VALUES (?, ?, ?, ?, ?, ?)
      ON CONFLICT DO NOTHING RETURNING 1 AS inserted
    `);

    for (const l of data.links) {
      stats.links += insertLink.get(
        l.sourceType,
        l.sourceId,
        l.targetType,
        l.targetId,
        l.relationship,
        l.weight
      ) ? 1 : 0;
    }

    // Import session-entity relationships (if present)
    if (data.sessionEntities && data.sessionEntities.length > 0) {
      using insertSessionEntity = db.prepare(`
        INSERT INTO session_entities
          (session_id, entity_id, frequency)
        VALUES (?, ?, ?)
      ON CONFLICT DO NOTHING
    `);

      for (const se of data.sessionEntities) {
        insertSessionEntity.run(se.sessionId, se.entityId, se.frequency);
      }
    }

    // Import entity-entity relationships (if present)
    if (data.entityLinks && data.entityLinks.length > 0) {
      using insertEntityLink = db.prepare(`
        INSERT INTO entity_links
          (source_id, target_id, relationship, weight)
        VALUES (?, ?, ?, ?)
      ON CONFLICT DO NOTHING
    `);

      for (const el of data.entityLinks) {
        insertEntityLink.run(
          el.sourceId,
          el.targetId,
          el.relationship,
          el.weight
        );
      }
    }

    // Import extraction states (if present)
    if (data.extractionStates && data.extractionStates.length > 0) {
      using insertState = db.prepare(`
        INSERT INTO extraction_state
          (id, session_path, started_at, status, completed_at,
           messages_extracted, error_message, file_mtime, file_size)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT DO NOTHING
    `);

      for (const es of data.extractionStates) {
        insertState.run(
          es.id,
          es.sessionPath,
          es.startedAt,
          es.status,
          es.completedAt,
          es.messagesExtracted,
          es.errorMessage,
          es.fileMtime,
          es.fileSize
        );
      }
    }

    // Import facts (if present)
