import ts from 'typescript';
import {readFileSync,writeFileSync} from 'node:fs';
import {strict as assert} from 'node:assert';
import {sourceHash} from '../scripts/quality-inventory';
const map=JSON.parse(readFileSync('.git/b11-combined-map.json','utf8')),repos=JSON.parse(readFileSync('.git/b11-core-lifetime-audit.json','utf8'));
const sources=new Map<string,string>(map.sources.map((r:any)=>[r.path,readFileSync(r.path,'utf8')]));
for(const r of repos.rows)assert.equal(sourceHash(sources.get(r.path)!),r.sourceHash);
function audit(input:Map<string,string>){return map.sites.filter((r:any)=>r.native&&r.name==='prepare').map((site:any)=>{
 const file=ts.createSourceFile(site.path,input.get(site.path)!,ts.ScriptTarget.Latest,true);let matched:ts.CallExpression|undefined;
 function walk(n:ts.Node){if(ts.isCallExpression(n)&&ts.isPropertyAccessExpression(n.expression)&&n.expression.name.text==='prepare'&&file.getLineAndCharacterOfPosition(n.getStart()).line+1===site.line)matched=n;ts.forEachChild(n,walk);}walk(file);assert(matched,'Missing mapped site');
 const scoped=ts.isVariableDeclaration(matched.parent)&&ts.isVariableDeclarationList(matched.parent.parent)&&!!(matched.parent.parent.flags&ts.NodeFlags.Using);
 if(!scoped){const repo=repos.rows.find((r:any)=>r.path===site.path);assert(ts.isReturnStatement(matched.parent)&&repo?.prepares.some((r:any)=>r.line===site.line&&r.lifetime==='returned to scoped helper callers'),'Unowned native statement '+site.path+':'+site.line);}
 return {path:site.path,line:site.line,lifetime:scoped?'local using scope':'returned to audited scoped helper callers'};
});}
const rows=audit(sources);assert.equal(rows.length,187);assert.equal(rows.filter((r:any)=>r.lifetime==='local using scope').length,179);
const show='src/presentation/cli/commands/show.ts',bad=new Map(sources);bad.set(show,sources.get(show)!.replace('using stmt =','const stmt ='));assert.throws(()=>audit(bad),/Unowned native statement/);
const ownership=map.sites.filter((r:any)=>r.classification==='native-connection-owner'||r.classification==='factory-connection-owner'||r.classification==='connection-disposal'||r.path==='src/presentation/cli/db-startup.ts'&&r.name==='initializeDatabaseSafe').map((r:any)=>({...r,verificationGroup:r.path.startsWith('src/presentation/')?'cli':r.path.startsWith('scripts/')?'application':'database',disposition:r.path==='src/infrastructure/database/owned-database.ts'?'Connection tracks and finalizes live statements; Reflect.apply delegates native prepare. Native retained/overflow/failure/retry tests required.':r.path==='src/presentation/cli/db-startup.ts'?'Injected factory transfers owned connection on success; callers close; factory cleans failed initialization.':r.path==='src/infrastructure/database/health-checker.ts'||r.path==='src/presentation/cli/commands/backup.ts'||r.path==='src/presentation/cli/commands/migrate.ts'?'Raw readonly/probe connections close in finally; native probes verify scoped statement disposal.':'Owning shared factory connection; callers close in finally. Group pass is scoped verification, not complete quality acceptance.'}));
writeFileSync('.git/b11-combined-ownership.json',JSON.stringify({recordedAt:new Date().toISOString(),sourceInputs:[...sources].map(([path,s])=>({path,sourceHash:sourceHash(s)})),rows,ownership,repositoryAudit:repos,negativeCheck:'Replacing show using with const is rejected by AST ownership audit.',limits:['Reflect.apply native delegation is source-inspected and covered by owner native tests, not a direct prepare AST call.','No full quality, declared runtime floor, Linux, installed artifact or external review acceptance.'],source:readFileSync('.git/b11-combined-ownership.ts','utf8')},null,2)+'\n');
console.log('187 prepares:179 local scopes,8 returned to audited scoped callers. Missing-scope negative rejected.');

